function dates(a,b){const out=[];for(let d=a;d<=b;d=C.addDay(d,1))out.push(d);return out}
function times(st){return {chockOn:S(st.h5Start||st.f421_h5Start),doorClose:S(st.h21Start||st.f421_h21Start),pushback:S(st.h24Start||st.f421_h24Start)}}
async function batch(items,fn){const out=[];for(let i=0;i<items.length;i+=8)out.push(...await Promise.all(items.slice(i,i+8).map(fn)));return out}
async function load(){if(locked)return;guard();const from=C.parse($('srFrom').value),to=C.parse($('srTo').value),sourceFrom=$('srSourceFrom').value,endDay=$('srTo').value.slice(0,10);if(!Number.isFinite(from)||!Number.isFinite(to)||to<=from||to-from>7*86400000)throw Error('Khoảng báo cáo phải lớn hơn 0 và tối đa 7 ngày.');if(!/^\d{4}-\d{2}-\d{2}$/.test(sourceFrom)||sourceFrom>$('srFrom').value.slice(0,10)||C.parse(sourceFrom+'T00:00')<from-31*86400000)throw Error('Ngày nguồn phải trước hoặc bằng ngày bắt đầu, tối đa 31 ngày trước.');
const q=query();lastQuery='';const sourceDays=dates(sourceFrom,endDay);status('Đang đọc hồ sơ chung, gồm chuyến đã hoàn thành…');const snapshots=await batch(sourceDays,async d=>[d,(await db('flight_records/'+safe(d)).once('value')).val()||{}]);let records=snapshots.flatMap(([d,v])=>Object.entries(v).map(([fid,r])=>({...r,flightId:r.flightId||fid,opDate:r.opDate||d})));
const candidateFrom=from-24*3600000,candidateTo=to+12*3600000,reportStartDay=C.day(from),reportEndDay=C.day(to-1);
const preTimeCandidate=r=>{try{const n=C.normalize(r,overrides[S(r.opDate)+'/'+S(r.flightId)]||{}),times=[n.sta,n.std,n.etd,n.on,n.door,n.pb].filter(Number.isFinite),op=S(r.opDate),dayMatch=op>=reportStartDay&&op<=reportEndDay,nearTime=times.some(t=>t>=candidateFrom&&t<candidateTo),carried=Number.isFinite(n.on)&&n.on<from&&(!Number.isFinite(n.pb)||n.pb>=from),unknown=dayMatch&&(!n.legs.length||n.legs.some(l=>!Number.isFinite(l.plan)));return nearTime||carried||unknown}catch(_){const op=S(r.opDate);return op>=reportStartDay&&op<=reportEndDay}};
const allSourceRecords=records,timeCandidates=records.filter(preTimeCandidate);let timeFilteredOut=allSourceRecords.length-timeCandidates.length,workspaceRejected=0;records=timeCandidates;
status('Đã lọc theo thời gian. Đang đọc workspace đúng chuyến…');
const cache=new Map();await batch(records,async r=>{const assignments=Object.values(r.assignments||{}).filter(a=>['FSAGS','FSAGS421','FSAGS423'].includes(U(a.formGroup))||/GRND_COR/.test(U(a.sourceColumn))),keys=[r.modules?.RAMP?.workspaceKey,...assignments.map(a=>a.workspaceKey||a.rosterWorkspaceKey)].filter(Boolean);let best=null;const candidates=[];for(const wk of [...new Set(keys)]){if(!cache.has(wk))cache.set(wk,db('roster_flight_workspaces/'+safe(wk)).once('value'));const w=(await cache.get(wk)).val();if(!w||S(w.flightId)!==S(r.flightId)){workspaceRejected++;continue}if(w?.envelope?.state)candidates.push({...w,_wk:wk});if(w?.envelope?.state&&(!best||Number(w.envelopeUpdatedAtMs||w.updatedAtMs)>Number(best.envelopeUpdatedAtMs||best.updatedAtMs)))best=w}if(best){r._ramp=times(best.envelope.state);for(const key of ['chockOn','doorClose','pushback']){const compatible=candidates.filter(w=>{const scopes=assignments.filter(a=>(a.workspaceKey||a.rosterWorkspaceKey)===w._wk).map(a=>U(a.assignmentScope||'BOTH'));return !scopes.length||scopes.some(s=>s==='BOTH'||(key==='chockOn'?!s.includes('DEP'):!s.includes('ARR')))}).sort((a,b)=>Number(b.envelopeUpdatedAtMs||b.updatedAtMs)-Number(a.envelopeUpdatedAtMs||a.updatedAtMs));if(compatible.length)r._ramp[key]=times(compatible[0].envelope.state)[key]}r._source='Biểu mẫu chung · '+S(best.workspaceKey);r.route1=r.route1||best.envelope.state.route1||best.envelope.state.f421_route1;r.route3=r.route3||best.envelope.state.route3||best.envelope.state.f421_route3}});
if($('srArchive').checked){status('Đang đối chiếu kho lưu trữ…');if(!root.sagsShiftReadArchive)throw Error('Chưa mở được mô-đun lưu trữ. Hãy tải lại ứng dụng.');for(const d of sourceDays){const old=await root.sagsShiftReadArchive(d,records),oldCandidates=old.filter(preTimeCandidate);timeFilteredOut+=old.length-oldCandidates.length;records.push(...oldCandidates)}}
if(!records.length)throw Error('Không tìm thấy hồ sơ trong khoảng nguồn. Chưa đủ dữ liệu để xác nhận sản lượng bằng 0.');status('Đang tổng hợp dữ liệu ca…');const incidentRecords=[];guard();if(q!==query())throw Error('Khoảng thời gian đã đổi trong lúc tải. Bấm TỔNG HỢP lại.');
raw=records;readAt=Date.now();lastQuery=q;model=C.aggregate(raw,from,to,readAt,overrides,$('srScope').value==='mine'?(model?.scopeUser||owner):'');model.coverage={from:sourceFrom,to:endDay,archive:$('srArchive').checked,strategy:'TIME_FIRST',timeFilteredOut,workspaceRejected};const ids=new Set(model.relevant.map(f=>f.flightId));const prior=new Map(events.map(x=>[x.id,x]));events=incidentRecords.filter(Boolean).filter(e=>e.occurredAtMs<to&&e.occurredAtMs<=readAt&&(e.occurredAtMs>=from||e.state!=='DONE'||Number(e.updatedAtMs)>from)).filter(e=>$('srScope').value!=='mine'||ids.has(e.flightId)||e.createdBy===owner).map(e=>({...e,selected:prior.get(e.id)?.selected??true,carried:e.occurredAtMs<from,afterCutoff:Number(e.updatedAtMs)>Math.min(to,readAt)}));render();saveLocal();status('Đã tổng hợp theo thời gian: '+model.relevant.length+' hồ sơ liên quan.'+(timeFilteredOut?' Đã loại '+timeFilteredOut+' hồ sơ ngoài cửa sổ trước khi đọc workspace.':'')+(workspaceRejected?' Đã bỏ '+workspaceRejected+' workspace không thuộc đúng flightId.':'')+' Rà soát số liệu và sự việc trước khi chốt.')}
function recalc(){if(!raw.length)return status('Nháp đã khôi phục: bấm TỔNG HỢP trước khi sửa đối chiếu.');const coverage=model.coverage;model=C.aggregate(raw,model.from,model.to,readAt,overrides,$('srScope').value==='mine'?(model?.scopeUser||owner):'');model.coverage=coverage;render();dirty()}
function fmt(t){return C.local(t).replace('T',' ')||'—'}
function legRow(l){return `<tr><td>${esc(l.num||l.label)}</td><td>${esc(l.route||'')}</td><td>${esc(l.reg)}</td><td>${esc(fmt(l.plan))}</td><td>${esc(fmt(l.actual))}</td><td>${esc(l.reason||l.change||'')}</td></tr>`}
function details(list){const table=document.createElement('div');table.className='srScroll';table.innerHTML='<table><thead><tr><th>Chuyến</th><th>Chặng</th><th>Đăng bạ</th><th>Kế hoạch</th><th>Thực tế</th><th>Lý do / ghi chú</th></tr></thead><tbody>'+list.map(legRow).join('')+'</tbody></table>';return table}
function render(){if(!model)return;const box=$('srResults');box.innerHTML=`<h3>2. Sản lượng phục vụ</h3><p>Khoảng ${esc(fmt(model.from))} → trước ${esc(fmt(model.to))}. Thực tế đến ${esc(fmt(model.cutoff))}. Nguồn hồ sơ ${esc(model.coverage?.from)}–${esc(model.coverage?.to)}${model.coverage?.archive?' + kho lưu trữ':' · chưa đọc kho lưu trữ'}.</p><p>${model.scopeUser?'BÁO CÁO CÁ NHÂN '+esc(model.scopeUser)+' · chỉ lấy chuyến được phân công.':'SẢN LƯỢNG TOÀN CA · không cộng báo cáo nhân viên.'} ${model.unassigned} hồ sơ trong phạm vi nguồn chưa có phân công.</p>`;
const table=document.createElement('table');table.innerHTML='<thead><tr><th>Hãng</th><th>QN/QT</th><th>Đến/đi</th><th>Kế hoạch</th><th>Đã thực hiện</th></tr></thead>';const body=document.createElement('tbody');model.groups.forEach(g=>{const tr=document.createElement('tr');for(const x of [g.airline,g.region,g.dir]){const td=document.createElement('td');td.textContent=x;tr.appendChild(td)}for(const k of ['planned','actual']){const td=document.createElement('td');td.appendChild(button(String(g[k].length),()=>{$('srDetail').replaceChildren(details(g[k]))}));tr.appendChild(td)}body.appendChild(tr)});table.appendChild(body);const scroll=document.createElement('div');scroll.className='srScroll';scroll.appendChild(table);box.appendChild(scroll);
const listTitles={planned:'Tổng lượt kế hoạch',actual:'Tổng lượt đã thực hiện',plannedPairs:'Cặp kế hoạch (tính tại STD)',pairs:'Cặp hoàn thành (tính tại PUSHBACK)',delays:'Chuyến chậm',remaining:'Dự kiến còn lại',missing:'Thiếu giờ thực tế sau giờ kế hoạch',received:'Tiếp nhận từ ca trước',open:'Đang mở / phục vụ',closed:'Đã Door Close, chưa PUSHBACK',handover:'Chuyến cần bàn giao',changes:'Thay đổi có nguồn'};const cards=document.createElement('div');cards.className='srActions';for(const [k,title] of Object.entries(listTitles))cards.appendChild(button(title+': '+model.lists[k].length,()=>{$('srDetail').replaceChildren(details(model.lists[k]))}));box.appendChild(cards);const detail=document.createElement('div');detail.id='srDetail';box.appendChild(detail);
const check=document.createElement('details');check.innerHTML='<summary>KIỂM TRA CHUYẾN / BỔ SUNG DỮ LIỆU ĐÃ XÁC MINH ('+model.warnings.length+' ghi chú)</summary><p>Chỉ sửa ở đây khi có nguồn xác nhận. Sửa phục vụ báo cáo này, không ghi đè hồ sơ khai thác.</p>';model.relevant.forEach(f=>{const card=document.createElement('article');card.innerHTML='<b>'+esc(f.label)+' · '+esc(f.reg)+'</b><p>'+esc(f.warnings.join(' · ')||f.source)+'</p>';const o=overrides[f.id]||{};for(const [k,label] of [['arrRegion','Phân loại đến'],['depRegion','Phân loại đi']]){if(k==='arrRegion'&&!f.arr||k==='depRegion'&&!f.dep)continue;const wrap=document.createElement('label');wrap.textContent=label;const s=document.createElement('select');for(const v of ['','QN','QT','CHƯA RÕ'])s.add(new Option(v||'Theo chặng nguồn',v));s.value=o[k]||'';s.disabled=locked||!raw.length;s.onchange=()=>{(overrides[f.id]||={})[k]=s.value;recalc()};wrap.appendChild(s);card.appendChild(wrap)}for(const [k,label,value] of [['chockOn','CHOCK ON',f.on],['doorClose','Door Close',f.door],['pushback','PUSHBACK',f.pb],['arrReason','Lý do đến chậm',''],['depReason','Lý do đi trễ','']]){const labelEl=document.createElement('label');labelEl.textContent=label;const input=document.createElement('input');input.type=k.includes('Reason')?'text':'datetime-local';input.value=o[k]||C.local(value)||'';input.disabled=locked||!raw.length;input.onchange=()=>{(overrides[f.id]||={})[k]=input.value;recalc()};labelEl.appendChild(input);card.appendChild(labelEl)}check.appendChild(card)});box.appendChild(check);
$('srEvents').replaceChildren();events.forEach(e=>{const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.checked=e.selected;input.disabled=locked;input.onchange=()=>{e.selected=input.checked;dirty()};label.append(input,document.createTextNode(' '+(e.carried?'BÀN GIAO TỪ TRƯỚC · ':'')+eventText(e)));$('srEvents').appendChild(label)});if(!events.length)$('srEvents').textContent='Chưa có ghi nhận trong nguồn đã chọn. Chỉ ghi NIL khi người lập xác nhận.';lockUi()}
function eventText(e){return `${e.afterCutoff?'[Có cập nhật sau giờ chốt; kết quả dưới đây là lúc lấy dữ liệu] ':''}${e.when?.replace('T',' ')||fmt(e.occurredAtMs)} · ${e.flightLabel||e.place||'Sự việc chung'}: ${e.content}${e.result?' | Xử lý/kết quả: '+e.result:''} | ${e.state==='DONE'?'Đã xử lý':e.state==='HANDOVER'?'Cần bàn giao':'Đang xử lý'}${(e.attachments||[]).map(x=>'\nTài liệu: '+x.url).join('')}`}
function snapshot(){if(locked&&frozen)return structuredClone(frozen);if(!model)throw Error('Bấm TỔNG HỢP trước.');if(lastQuery!==query())throw Error('Thời gian/phạm vi đã đổi. Bấm TỔNG HỢP lại.');const notes={};for(const k of notesFields)notes[k]=$(k).value;const selected=events.filter(e=>e.selected);if($('srNil').checked&&(selected.some(e=>!e.carried)||S(notes.srIncidentNote)))throw Error('Không thể ghi NIL khi có sự việc trong ca hoặc nội dung bổ sung.');return {schema:1,version:'V4.2.24',reportId,reportDay,revision:0,expected,token,actor:owner,atMs:Date.now(),model:structuredClone(model),events:structuredClone(selected),notes,nil:$('srNil').checked,excludedEvents:events.filter(e=>!e.selected).map(e=>e.id),overrides:Object.entries(overrides).map(([id,values])=>({id,values:structuredClone(values)}))}}
async function finalize(){if(locked)return;if(!$('srReviewed').checked)throw Error('Cần xác nhận đã kiểm tra dữ liệu và nội dung.');const s=snapshot();if(!S(s.notes.srPeople))throw Error('Cần nhập người trực/người lập.');if(!navigator.onLine)throw Error('Đang ngoại tuyến. Có thể LƯU NHÁP; có mạng mới chốt.');s.revision=expected+1;s.status='CHỐT';const expectedNow=expected,path='shift_reports/'+safe(reportDay)+'/'+safe(reportId);status('Đang chốt bản R'+s.revision+'…');for(const k of [...notesFields,'srFrom','srTo','srSourceFrom','srScope','srArchive','srNil','srReviewed'])$(k).disabled=true;const result=await timeout(db(path).transaction(old=>{if(old?.revisions?.[s.revision]?.token===token)return old;if(Number(old?.latest||0)!==expectedNow)return;return {...(old||{}),reportId,reportDay,latest:s.revision,revisions:{...(old?.revisions||{}),[s.revision]:s}}}),20000);guard();if(!result.committed)throw Error('Đã có bản mới được chốt. Mở lịch sử bản mới nhất trước khi tạo UPDATE.');frozen=result.snapshot.val().revisions[s.revision];expected=s.revision;locked=true;lockUi();saveLocal();$('srPreviewBody').innerHTML=html(frozen);status('ĐÃ CHỐT R'+expected+' · '+fmt(frozen.atMs)+'. Chưa tự gửi cho người khác.')}
function timeout(p,ms){return new Promise((resolve,reject)=>{const t=setTimeout(()=>reject(Error('Chưa xác nhận được kết quả chốt. Hãy xem lịch sử hoặc thử CHỐT lại; cùng mã bản sẽ không tạo trùng.')),ms);Promise.resolve(p).then(v=>{clearTimeout(t);resolve(v)},e=>{clearTimeout(t);reject(e)})})}
function text(s){const m=s.model,n=s.notes,l=m.lists,parts=[];parts.push('BÁO CÁO KHAI THÁC CA TRỰC',s.revision?'BẢN CHỐT R'+s.revision:'BẢN NHÁP','1. THÔNG TIN CA TRỰC',`Từ ${fmt(m.from)} đến trước ${fmt(m.to)} (giờ Việt Nam).`,`Thực tế đến ${fmt(m.cutoff)}; lấy dữ liệu ${fmt(m.asOf)}.`,`Phạm vi: ${m.scopeUser?'Cá nhân '+m.scopeUser:'Toàn ca'}. Người trực/người lập: ${n.srPeople||'CHƯA NHẬP'}.`,`Nguồn hồ sơ: ${m.coverage.from}–${m.coverage.to}${m.coverage.archive?' và kho lưu trữ':' (không đọc kho lưu trữ)'}.`,'','2. SẢN LƯỢNG PHỤC VỤ','Hãng | QN/QT | Đến/đi | Kế hoạch | Đã thực hiện');m.groups.forEach(g=>parts.push(`${g.airline} | ${g.region} | ${g.dir} | ${g.planned.length} | ${g.actual.length}`));parts.push(`Tổng lượt: kế hoạch ${l.planned.length}; đã thực hiện ${l.actual.length}.`,`Cặp kế hoạch: ${l.plannedPairs.length}; cặp hoàn thành: ${l.pairs.length} (một cặp đến–đi, tính tại PUSHBACK; không cộng vào tổng lượt).`,`Đến theo CHOCK ON; đi theo PUSHBACK. Thiếu giờ thực tế: ${l.missing.length} lượt.`,'','3. CHẬM CHUYẾN VÀ THAY ĐỔI KHAI THÁC');l.delays.forEach(x=>parts.push(x.dir==='ĐI'?`${x.num} ${x.route} STD ${C.local(x.plan).slice(11).replace(':','')}${Number.isFinite(x.etd)?'/ETD '+C.local(x.etd).slice(11).replace(':',''):''}: tàu đóng cửa ${C.local(x.door).slice(11).replace(':','')}, trễ ${x.delay}' so với STD. Lý do: ${x.reason||'CHƯA CÓ NGUỒN'}.`:`${x.num} ${x.route} STA ${fmt(x.plan)}: CHOCK ON ${fmt(x.actual)}, chậm ${x.delay}'. Lý do: ${x.reason||'CHƯA CÓ NGUỒN'}.`));if(!l.delays.length)parts.push('Chưa ghi nhận chuyến chậm từ các mốc có dữ liệu; không kết luận các chuyến thiếu giờ là đúng giờ.');l.changes.forEach(x=>parts.push(x.num+': '+x.change));if(n.srChanges)parts.push(n.srChanges);parts.push('','4. SỰ VIỆC TRONG CA');const current=s.events.filter(e=>!e.carried);parts.push(...current.map(eventText));if(n.srIncidentNote)parts.push(n.srIncidentNote);if(!current.length&&!n.srIncidentNote)parts.push(s.nil?'NIL (người lập xác nhận)':'CHƯA XÁC NHẬN KHÔNG PHÁT SINH');parts.push('','5. CÔNG VIỆC CÒN LẠI VÀ BÀN GIAO',`Tiếp nhận từ ca trước: ${l.received.map(f=>f.label).join(', ')||'Chưa có trong nguồn'}.`,`Đang mở/phục vụ: ${l.open.map(f=>f.label).join(', ')||'Chưa có trong nguồn'}.`,`Đã Door Close, chưa PUSHBACK: ${l.closed.map(f=>f.label).join(', ')||'Chưa có trong nguồn'}.`,`Dự kiến còn lại đến cuối khoảng chọn: ${l.remaining.map(f=>f.num+' '+f.route+' '+fmt(f.plan)).join('; ')||'Chưa có trong nguồn'}.`);parts.push(...s.events.filter(e=>e.state!=='DONE'||e.afterCutoff).map(eventText));if(n.srHandover)parts.push(n.srHandover);parts.push('','6. ĐỀ XUẤT / KIẾN NGHỊ',n.srAdvice||'CHƯA NHẬP','',`Ghi chú kiểm tra: ${m.warnings.length?m.warnings.join('; '):'Không có ghi chú phân loại/ngày giờ.'}`,`Lượt thiếu giờ thực tế: ${l.missing.map(x=>x.num+' '+x.dir).join(', ')||'Không có trong danh sách đã tính'}.`,`Số hồ sơ có dữ liệu xác nhận bổ sung riêng cho báo cáo: ${Object.keys(s.overrides||{}).length}.`,`Sự việc không chọn đưa vào báo cáo: ${s.excludedEvents.length}.`,`Chốt/lập: ${fmt(s.atMs)} · ${s.actor}${s.revision?' · R'+s.revision:''}.`);return parts.join('\n')}
function html(s){const full=text(s),start=full.indexOf('2. SẢN LƯỢNG PHỤC VỤ'),summary=full.indexOf('Tổng lượt:'),rows=s.model.groups.map(g=>'<tr>'+[g.airline,g.region,g.dir,g.planned.length,g.actual.length].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('');return '<article class="srDocument"><pre>'+esc(full.slice(0,start))+'</pre><h3>2. SẢN LƯỢNG PHỤC VỤ</h3><table><thead><tr><th>Hãng</th><th>QN/QT</th><th>Đến/đi</th><th>Kế hoạch</th><th>Đã thực hiện</th></tr></thead><tbody>'+rows+'</tbody></table><pre>'+esc(full.slice(summary))+'</pre><h3>Phụ lục đối chiếu chuyến</h3><div class="srScroll"><table><thead><tr><th>Chuyến</th><th>Chặng</th><th>Đăng bạ</th><th>STA/STD</th><th>CHOCK ON/PUSHBACK</th><th>Ghi chú</th></tr></thead><tbody>'+s.model.relevant.flatMap(f=>f.legs).map(legRow).join('')+'</tbody></table></div></article>'}
