  let fleetAir='';try{if(reg)fleetAir=S(root.fleetInfo?.(reg)?.airline)}catch(_){}
  return {sid,meta:meta0,st,flights,reg,fleetAir,label:flights.join(' / ')||S(meta0?.name)||'CHƯA CÓ SỐ CHUYẾN'};
